    jxtp_longfan: {
        enable: 'phaseUse',
        usable: 1,
        content() {
            'step 0';
            player.judge(function (card) {
                switch (card.suit) {
                    case 'heart':
                        return player.maxHp > player.hp ? 2 : 1;
                    case 'diamond':
                        return 2;
                    case 'club':
                        return 1;
                    case 'spade':
                        return 1;
                }
            });
            ('step 1');
            switch (result.suit) {
                case 'heart': {
                    if (player.isDamaged()) {
                        player.recover();
                    } else {
                        player.changeHujia();
                    }
                    break;
                }
                case 'diamond': {
                    player.draw();
                    let list = [];
                    get.cardPile(function (card) {
                        if (card.name != 'du' && get.color(card) == 'red') {
                            list.push(card);
                        }
                    });
                    if (list.length) {
                        player.gain(list.randomGet(), 'draw');
                        game.log(player, '获得了一张红色牌');
                    }
                    break;
                }
                case 'club': {
                    let targets = player.getEnemies();
                    for (let i = 0; i < targets.length; i++) {
                        if (!targets[i].countGainableCards(player, 'he')) {
                            targets.splice(i--, 1);
                        }
                    }
                    if (targets.length) {
                        let target = targets.randomGet();
                        player.line(target);
                        player.gainPlayerCard('he', target, true);
                    }
                    break;
                }
                case 'spade': {
                    let targets = player.getEnemies();
                    if (targets.length) {
                        let target = targets.randomGet();
                        player.line(target);
                        target.loseHp();
                    }
                    break;
                }
            }
        },
        ai: {
            order: 10,
            result: {
                player: 1,
            },
        },
    },
