            content() {
                'step 0';
                event.num = 2;
                event.type = 'equip';
                ('step 1');
                let list = [];
                event.list = list;
                for (const i of lib.inpile) {
                    if (lib.filter.filterCard({ name: i }, target)) {
                        let info = lib.card[i];
                        if (info.type == event.type && !info.multitarget && !info.notarget) {
                            if (Array.isArray(info.selectTarget)) {
                                if (info.selectTarget[0] > 0 && info.selectTarget[1] >= info.selectTarget[0]) {
                                    list.push(i);
                                }
                            } else if (typeof info.selectTarget == 'number') {
                                list.push(i);
                            }
                        }
                    }
                }
                ('step 2');
                let list1 = event.list;
                while (list1.length) {
                    let card = { name: list1.randomRemove() };
                    let info = get.info(card);
                    let targets = game.filterPlayer(function (current) {
                        return lib.filter.filterTarget(card, target, current);
                    });
                    if (targets.length) {
                        targets.sort(lib.sort.seat);
                        if (info.selectTarget == -1) {
                            target.useCard(event.type == 'equip' ? game.createCard(card) : card, targets, 'noai');
                        } else {
                            let num = info.selectTarget;
                            if (Array.isArray(num)) {
                                if (targets.length < num[0]) {
                                    continue;
                                }
                                num = num[0] + Math.floor(Math.random() * (num[1] - num[0] + 1));
                            } else {
                                if (targets.length < num) {
                                    continue;
                                }
                            }
                            target.useCard(event.type == 'equip' ? game.createCard(card) : card, targets.randomGets(num), 'noai');
                        }
                        if (--event.num > 0) {
                            event.type = 'trick';
                            event.goto(1);
                        }
                        break;
                    }
                }
            },
            ai: {
                order: 7,
                useful: 2,
                value: 7,
                result: {
                    target: 1,
                },
            },
