    linmo_g_chiling3: {
        //mode:.guozhan,
        trigger: { player: 'phaseEnd' },
        forced: true,
        popup: false,
        filter(event, player) {
            return _status.linmochiling == true;
        },
        content() {
            'step 0';
            _status.linmochiling = false;
            let targets = game.filterPlayer();
            targets.sort(lib.sort.seat);
            event.targets = targets;
            game.playAudio('../audio', 'card', 'male', 'chiling.mp3');
            game.playAudio('../audio', 'card', 'female', 'chiling.mp3');
            ('step 1');
            if (event.targets.length) {
                let target = event.targets.shift();
                event.current = target;
                let list = [],
                    list2 = ['明置一张武将牌并摸一张牌', '交给' + get.translation(player) + '一张装备牌', '失去一点体力'];
                if (target.isUnseen(1) || target.isUnseen(0)) {
                    list.push('选项一');
                }
                if (target.countCards('he', { type: 'equip' })) {
                    list.push('选项二');
                }
                list.push('选项三');
                target
                    .chooseControl(list)
                    .set('choiceList', list2)
                    .set('ai', function () {
                        if (target.isUnseen(1) || target.isUnseen(0)) {
                            return '选项一';
                        }
                        if (target.countCards('he', { type: 'equip' })) {
                            return '选项二';
                        }
                        return '选项三';
                    });
            } else {
                event.finish();
            }
            ('step 2');
            let target = event.current;
            event.control = result.control;
            if (result.control == '选项一') {
                if (!target.isUnseen(0)) {
                    target.showCharacter(1);
                } else if (!target.isUnseen(1)) {
                    target.showCharacter(0);
                } else {
                    target
                        .chooseControl('主将', '副将', function () {
                            return Math.floor(Math.random() * 2);
                        })
                        .set('prompt', '选择要明置的武将牌');
                }
            }
            if (result.control == '选项二') {
                target.chooseToDiscard('he', true, function (card) {
                    return get.type(card) == 'equip';
                });
            }
            if (result.control == '选项三') {
                target.loseHp();
                event.finish();
            }
            ('step 3');
            let target1 = event.current;
            if (event.control == '选项一') {
                if (result.index == 0) {
                    target1.showCharacter(0);
                } else {
                    target1.showCharacter(1);
                }
                target1.draw();
            }
            event.goto(1);
        },
    },
