                    let card;
                    if (num == 1) {
                        card = target.getCards('h').randomGet();
                    }
                    if (num > 1) {
                        card = target.getCards('h').randomGets(num);
                    }
                    player.gain(card, target, 'giveAuto', 'bySelf');
