        mym_chaoronghe: {
            //超融合
            type: 'mym_mofa',
            enable: true,
            notarget: true,
            content() {
                const chaoronghe = [];
                const crh = 'mym_chaorongheskill';
                for (let i = 0; i < 10000; i++) {
                    if (lib.skill[crh + i]) {
                        chaoronghe.push(crh + i);
                    }
                }
                let name = crh + chaoronghe.length;
                let skill = [];
                let targets = game
                    .filterPlayer(function (current) {
                        return current != player;
                    })
                    .sortBySeat();
                for (const i of targets) {
                    const skillList = [];
                    if (!i.isUnseen(0)) {
                        skillList.addArray(lib.character[i.name][3]);
                    }
                    if (i.name2 && !i.isUnseen(1)) {
                        skillList.addArray(lib.character[i.name2][3]);
                    }
                    for (const item of skillList) {
                        if (lib.translate[item + '_info'] && !skill.includes(item) && !player.hasSkill(item)) {
                            skill.add(item);
                        }
                    }
                }
                if (!skill.length) {
                    game.log('未在场上发现你未拥有的技能');
                    event.finish();
                    return;
                }
                if (chaoronghe.length) {
                    for (let s of chaoronghe) {
                        skill.remove(s);
                        if (player.hasSkill(s)) {
                            let o = lib.skill[s].group;
                            for (const a of o) {
                                skill.remove(a);
                            }
                        }
                    }
                }
                if (!skill.length) {
                    game.log('未在场上发现你未拥有的技能');
                    event.finish();
                    return;
                }
                if (skill.length > 3) {
                    skill = skill.randomGets(3);
                }
                let translation = '';
                let str = '';
                if (!lib.skill[name]) {
                    lib.skill[name] = { nobracket: true, group: [] };
                }
                for (let i = 0; i < skill.length; i++) {
                    lib.skill[name].group.push(skill[i]);
                    let group = lib.skill[skill[i]].group || [];
                    if (typeof group == 'string') {
                        lib.skill[name].group.push(group);
                    } else {
                        for (const items of group) {
                            lib.skill[name].group.push(items);
                        }
                    }
                    let br = '<br>';
                    if (i == skill.length - 1) {
                        br = '';
                        if (skill.length < 3) {
                            br = '<br><b>已无更多你未拥有的技能</b>';
                        }
                    }
                    translation += '<b>' + get.translation(skill[i]) + ':</b>' + get.translation(skill[i] + '_info') + br;
                    str += '【' + get.translation(skill[i]) + '】、';
                }
                lib.translate[name] = '超融合';
                lib.translate[name + '_info'] = translation;
                player.addSkill(name);
                let list = [name];
                game.broadcastAll(function (list) {
                    lib.character[player.name][3].addArray(list);
                    game.expandSkills(list);
                }, list);
                str = str.slice(0, str.length - 1);
                game.log(player, '将', '#g' + str, '融合添加到武将牌上');
            },
            ai: {
                result: {
                    player: 1,
                },
                order: 14,
                useful: 5,
                value: 8,
            },
            fullskin: true,
            image: 'ext:猫猫叹气/image/百宝箱/mym_chaoronghe.png',
        },
