        xdz_jiyidetouzhi: {
            //记忆的透支
            fullskin: true,
            type: 'trick',
            derivation: 'xdz_diyumoshenx',
            enable: true,
            filterTarget(card, player, target) {
                return player != target;
            },
            content() {
                'step 0';
                let card = get.cards()[0];
                event.card = card;
                game.cardsGotoOrdering(event.card);
                if (player.hp > 1) {
                    player.loseHp(Math.floor(player.hp / 2));
                }
                player
                    .chooseControl('basic', 'trick', 'equip', '其他')
                    .set('ai', function () {
                        if (get.type(card) == 'basic') {
                            return 'basic';
                        }
                        if (get.type(card, 'trick') == 'trick') {
                            return 'trick';
                        }
                        if (get.type(card) == 'equip') {
                            return 'equip';
                        }
                        return '其他';
                    })
                    .set('prompt', '猜测一种类型');
                ('step 1');
                game.log(player, '猜测的类型为', get.translation(result.control) || result.control, '牌');
                player.showCards(card);
                ('step 2');
                if ((result.control == '其他' && get.type(card, 'trick') != 'basic' && get.type(card, 'trick') != 'trick' && get.type(card, 'trick') != 'equip') || get.type(card, 'trick') == result.control) {
                    let hp1 = player.hp;
                    const hp2 = target.hp;
                    player.popup('洗具', 'metal');
                    if (player.maxHp < hp2) {
                        player.maxHp = hp2;
                    }
                    if (target.maxHp < hp1) {
                        target.maxHp = hp1;
                    }
                    player.hp = Math.min(player.maxHp, hp2);
                    target.hp = Math.min(target.maxHp, hp1);
                    player.update();
                    target.update();
                    game.log(player, '和', target, '交换了体力值');
                } else {
                    player.popup('杯具', 'metal');
                }
                ('step 3');
                card.fix();
                ui.cardPile.insertBefore(card, ui.cardPile.firstChild);
                game.updateRoundNumber();
            },
            ai: {
                tag: {
                    xdz: 1,
                },
                basic: {
                    order: 21,
                    value: 8,
                    useful: 4,
                },
                result: {
                    target(player, target) {
                        if (player.getFriends().includes(target)) {
                            return 0;
                        }
                        if (target.hp <= Math.ceil(player.hp / 2)) {
                            return 0;
                        }
                        return -target.hp - Math.ceil(player.hp / 2) - 1;
                    },
                },
            },
            selectTarget: 1,
            image: 'ext:猫猫叹气/image/百宝箱/xdz_jiyidetouzhi.png',
        },
