        xdz_shijianduantu: {
            //时间断屠
            type: 'trick',
            derivation: 'xdz_diyumoshenx',
            content() {
                'step 0';
                player
                    .chooseControl('准备阶段', '判定阶段', '摸牌阶段', '出牌阶段', '弃牌阶段', '结束阶段')
                    .set('ai', function () {
                        if (get.attitude(player, target) > 0 && target.countCards('j')) {
                            return '判定阶段';
                        }
                        if (get.attitude(player, target) <= 0 && target.storage.xdz_shenlvexskip_draw == true) {
                            return '出牌阶段';
                        }
                        if (get.attitude(player, target) <= 0 && target.storage.xdz_shenlvexskip_use == true) {
                            return '摸牌阶段';
                        }
                        if (get.attitude(player, target) <= 0 && (target.countCards('h') > 3 || target.hp < 2)) {
                            return '出牌阶段';
                        }
                        if (get.attitude(player, target) <= 0 && target.countCards('h') < 4) {
                            return '摸牌阶段';
                        }
                        return '弃牌阶段';
                    })
                    .set('prompt', '时间断屠:选择跳过' + get.translation(target) + '一个阶段');
                ('step 1');
                game.log(target, '跳过', '#y' + result.control);
                if (result.control == '准备阶段') {
                    target.skip('phaseZhunbei');
                }
                if (result.control == '判定阶段') {
                    target.skip('phaseJudge');
                }
                if (result.control == '摸牌阶段') {
                    target.skip('phaseDraw');
                }
                if (result.control == '出牌阶段') {
                    target.skip('phaseUse');
                }
                if (result.control == '弃牌阶段') {
                    target.skip('phaseDiscard');
                }
                if (result.control == '结束阶段') {
                    target.skip('phaseJieshu');
                }
            },
            ai: {
                value: 8,
                useful: 8,
                order: 1,
                result: {
                    target(player, target) {
                        if ((target.countCards('j') || target.countCards('h') > target.hp) && get.attitude(player, target) > 0) {
                            return 2;
                        }
                        if (get.attitude(player, target) <= 0) {
                            return -1;
                        }
                        return 0;
                    },
                },
                tag: {
                    xdz: 1,
                    skip: 'phaseUse',
                },
            },
            global: 'xdz_shijianduantuskill',
            fullskin: true,
            image: 'ext:猫猫叹气/image/百宝箱/xdz_shijianduantu.png',
        },
