        sgjl_baoxiang: {
            //宝箱
            type: 'trick',
            enable: true,
            toself: true,
            filterTarget(card, player, target) {
                return player == target;
            },
            selectTarget: -1,
            modTarget: true,
            content() {
                'step 0';
                target.throwDice();
                ('step 1');
                switch (num) {
                    case 1: {
                        game.countPlayer(function (current) {
                            if (player.isFriendsOf(current)) {
                                player.line(current, 'green');
                                current.gainMaxHp();
                                current.recover();
                            }
                        });
                        event.finish();
                        break;
                    }
                    case 2: {
                        if (ui.discardPile.childNodes.length) {
                            let dialog = ui.create.dialog('上古宝箱', '选择一张牌获得', 'hidden');
                            dialog.add(Array.from(ui.discardPile.childNodes));
                            player.chooseButton(dialog, true).set('ai', function (button) {
                                return get.value(button.link);
                            });
                        } else {
                            game.log('弃牌堆无可获得的牌');
                            event.finish();
                        }
                        break;
                    }
                    case 3: {
                        player.draw(2);
                        event.finish();
                        break;
                    }
                    case 4: {
                        player.chooseTarget(
                            '上古宝箱:获得一名其他角色的一张牌',
                            function (card, player, target) {
                                return target.isAlive() && target != player && target.countGainableCards(player, 'he');
                            },
                            function (target) {
                                let att = get.attitude(_status.event.player, target);
                                return -att;
                            },
                        );
                        break;
                    }
                    case 5: {
                        player.chooseTarget(
                            '上古宝箱:弃置一名其他角色的两张牌',
                            function (card, player, target) {
                                return target.isAlive() && target != player && target.countDiscardableCards(player, 'he');
                            },
                            function (target) {
                                let att = get.attitude(_status.event.player, target);
                                return -att;
                            },
                        );
                        break;
                    }
                    case 6: {
                        game.countPlayer(function (current) {
                            if (player.getEnemies().includes(current)) {
                                player.line(current, 'green');
                                if (current.countCards('e')) {
                                    current.discard(current.getCards('e'));
                                } else {
                                    current.discard(current.getCards('h').randomGets(2));
                                }
                            }
                        });
                        event.finish();
                        break;
                    }
                }
                event.num = num;
                ('step 2');
                if (result.bool) {
                    switch (event.num) {
                        case 2: {
                            player.gain(result.links, 'draw2');
                            break;
                        }
                        case 4: {
                            player.line(result.targets[0], 'green');
                            player.gainPlayerCard(true, 'he', result.targets[0]);
                            break;
                        }
                        case 5: {
                            player.line(result.targets[0], 'green');
                            player.discardPlayerCard(true, 'he', 2, result.targets[0]);
                            break;
                        }
                    }
                }
            },
            ai: {
                order: 10,
                value: 8,
                useful: 1,
                result: {
                    target: 1,
                },
                tag: {
                    gainMaxHp: 1,
                    recover: 1,
                    gain: 1,
                    draw: 2,
                    discard: 2,
                    lose: 2,
                },
            },
            fullskin: true,
            image: 'ext:猫猫叹气/image/上古降灵/sgjl_baoxiang.png',
        },
