    qmm_shengyan: {
        audio: 'ext:猫猫叹气/audio:2',
        enable: 'phaseUse',
        usable: 3,
        content() {
            'step 0';
            const lists = [];
            for (let i in lib.card) {
                if (!lib.translate[i + '_info']) {
                    continue;
                }
                if (!lib.card[i].content) {
                    continue;
                }
                if (lib.card[i].mode && lib.card[i].mode.includes(lib.config.mode) == false) {
                    continue;
                }
                if (lib.config.hiddenCardPack.indexOf(i) == 0) {
                    continue;
                }
                if (get.type(i) == 'equip') {
                    continue;
                }
                if (get.type(i) == 'basic') {
                    continue;
                }
                if (get.type(i) == 'gwmaoxian') {
                    continue;
                }
                if (get.subtype(i) == 'spell_gold') {
                    continue;
                }
                if (lib.card[i].chongzhu) {
                    continue;
                }
                if (!player.hasUseTarget(i)) {
                    continue;
                }
                if (['gw_dieyi_judge', 'yanxiao_card', 'nsfuzhou_card'].includes(i)) {
                    continue;
                }
                lists.push(i);
            }
            if (!lists.length) {
                event.finish();
                return;
            }
            let dialog = ui.create.dialog('<font size=5>【圣宴】', '选择一张牌交给任意一名角色', [lists.randomGets(5), 'vcard'], 'hidden');
            player.chooseButton(dialog, true).ai = function (button) {
                if (player.hasUseTarget(button.link[2])) {
                    return 1000 + Math.random();
                }
                return get.value({ name: button.link[2] }) + Math.random();
            };
            ('step 1');
            if (!result.bool) {
                event.finish();
                return;
            }
            player.chooseTarget(
                '选择一名角色获得' + get.translation(result.links[0][2]),
                true,
                function (card, player, target) {
                    return target.isAlive();
                },
                function (target) {
                    let att = get.attitude(_status.event.player, target);
                    return att;
                },
            );
            event.card = result.links[0][2];
            ('step 2');
            if (!result.bool) {
                event.finish();
                return;
            }
            let card = game.createCard(event.card);
            player.line(result.targets[0]);
            result.targets[0].gain(card, 'draw2');
            player.storage.qmm_qifux = event.card;
        },
        ai: {
            basic: {
                order: 0.3,
            },
            result: {
                player: 1,
            },
        },
        group: ['qmm_shengyan_draw', 'qmm_shengyan_use', 'qmm_shengyan_add'],
        subSkill: {
            draw: {
                trigger: {
                    player: ['phaseAfter'],
                },
                _priority: 1,
                audio: 'qmm_shengyan',
                forced: true,
                prompt2: '你可以将手牌摸至五张',
                content() {
                    player.drawTo(5);
                },
                filter(event, player) {
                    return player.countCards('h') < 5;
                },
            },
            use: {
                trigger: {
                    global: ['useCardAfter'],
                },
                filter(event, player) {
                    return (
                        _status.currentPhase != player &&
                        event.player != player &&
                        !player.hasSkill('qmm_shengyan_count') &&
                        player.countCards('h', function (cardx) {
                            return get.type(cardx) == 'basic' && player.hasUseTarget(cardx);
                        }) &&
                        get.type(event.card) == 'basic'
                    );
                },
                _priority: 1000,
                forced: true,
                content() {
                    let next = player.chooseToUse();
                    next.filterCard = function (card) {
                        return get.type(card) == 'basic' && player.hasUseTarget(card);
                    };
                    next.prompt = '是否使用一张基本牌？';
                },
            },
            count: {},
            add: {
                trigger: { player: 'useCard1' },
                prompt: -2,
                forced: true,
                filter(event, player) {
                    return event.getParent(2).name == 'qmm_shengyan_use';
                },
                content() {
                    player.addTempSkill('qmm_shengyan_count');
                },
            },
        },
    },
