    qmm_chunqing: {
        trigger: {
            global: ['phaseBefore', 'changeHp', 'die'],
            player: 'enterGame',
        },
        forced: true,
        forceDie: true,
        audio: 'ext:猫猫叹气/audio:2',
        filter(event, player, name) {
            if (name == 'die') {
                return player.storage.qmm_chunqing2 && [player.storage.qmm_chunqing2, player].includes(event.player) && event.player.countCards('he') > 0;
            }
            if (name == 'changeHp') {
                return player.storage.qmm_chunqing2 && [player.storage.qmm_chunqing2, player].includes(event.player) && player.storage.qmm_chunqing2.isAlive();
            }
            return !player.storage.qmm_chunqing2 && (event.name != 'phase' || game.phaseNumber == 0);
        },
        content() {
            'step 0';
            if (event.triggername == 'changeHp') {
                event.count = Math.abs(trigger.num);
                return;
            }
            if (event.triggername == 'die') {
                if (trigger.player == player) {
                    player.storage.qmm_chunqing2.gain(player.getCards('he'), player, 'giveAuto');
                } else {
                    player.gain(player.storage.qmm_chunqing2.getCards('he'), player.storage.qmm_chunqing2, 'giveAuto');
                }
                return;
            }
            //player.removeSkill('xunyi2');
            let t = true;
            if (
                !game.hasPlayer(function (current) {
                    return current.hasSex('male') && current != player;
                })
            ) {
                t = 1;
            }
            player.chooseTarget(
                get.prompt2('qmm_chunqing'),
                get.translation('qmm_chunqing_info'),
                t,
                function (card, player, target) {
                    return target.isAlive() && target != player && target.hasSex('male');
                },
                function (target) {
                    return get.attitude(target, player);
                },
            );
            ('step 1');
            if (event.triggername == 'changeHp') {
                event.count--;
                game.asyncDraw([player, player.storage.qmm_chunqing2]);
                return;
            }
            if (result.bool) {
                let target = result.targets[0];
                player.storage.qmm_chunqing2 = target;
                target.addSkill('qmm_chunqing_mark');
                if (!target.storage.qmm_chunqing_mark) {
                    target.storage.qmm_chunqing_mark = [];
                }
                target.storage.qmm_chunqing_mark.push(player);
                //target.addMark('qmm_chunqing_mark',1);
            }
            ('step 2');
            if (event.triggername == 'changeHp') {
                if (event.count > 0 && player.storage.qmm_chunqing2 && player.storage.qmm_chunqing2.isAlive()) {
                    event.goto(1);
                }
                return;
            }
        },
        subSkill: {
            mark: {
                marktext: '夫',
                mark: true,
                intro: {
                    name: '夫君',
                    content(storage, player, skill) {
                        return get.translation(storage) + '的夫君';
                    },
                },
            },
        },
    },
