    qmm_luansha: {
        audio: 'ext:猫猫叹气/audio:2',
        forced: true,
        round: 3,
        trigger: { player: 'phaseUseBegin' },
        content() {
            'step 0';
            game.asyncDraw(
                game.filterPlayer(function (current) {
                    return !current.countCards('h');
                }),
                2,
            );
            ('step 1');
            let sha = game.filterPlayer(function (current) {
                return current.countCards('hs', 'sha');
            });
            const nosha = game.filterPlayer(function (current) {
                return current.countCards('hesj');
            });
            if ((!sha.length && !nosha.length) || !player.isAlive()) {
                return;
            }
            let target = nosha.randomGet();
            if (sha.length) {
                target = sha.randomGet();
            }
            let card = [target.getCards('hejs').randomGet()];
            if (target.countCards('hs', 'sha')) {
                card = [target.getCards('hs', 'sha').randomGet()];
            }
            let target1 = game
                .filterPlayer(function (current) {
                    return current != target;
                })
                .randomGet();
            if (card[0].name == 'sha') {
                target.useCard(card[0], target1, false);
            } else {
                target.useCard({ name: 'sha' }, target1, card, false);
            }
            event.redo();
        },
    },
