    qysj_juyan: {
        audio: 'yiji',
        intro: {
            mark(dialog, content, player) {
                if (content) {
                    dialog.addText('当前<拒言>技能:');
                    dialog.addText(get.translation(content));
                }
            },
        },
        trigger: {
            global: 'qmmUseSkillEnd',
        },
        logTarget: 'player',
        check(event, player) {
            return true;
        },
        filter(event, player) {
            if (event.player == player) {
                return false;
            }
            let skill = event.skill;
            const skills = event.player.getSkills(true, false);
            for (let s of skills) {
                let group = lib.skill[s].group || [];
                if (typeof group == 'string') {
                    if (group == skill) {
                        skill = s;
                    }
                } else {
                    for (const item of group) {
                        if (item == skill) {
                            skill = s;
                        }
                    }
                }
            }
            if (skill == event.skill && !skills.includes(skill)) {
                return false;
            }
            return lib.skill[skill] && lib.translate[skill] && lib.translate[skill + '_info'] && !player.hasSkill(skill);
        },
        prompt2(event, player) {
            return '获得' + get.translation(event.player) + '发动的技能【' + get.translation(event.skill) + '】' + (player.storage.qysj_juyan ? ',并替换当前的<拒言>技能【' + get.translation(player.storage.qysj_juyan) + '】' : '');
        },
        content() {
            'step 0';
            let skill = trigger.skill;
            if (!player.hasSkill(skill)) {
                if (player.storage.qysj_juyan) {
                    player.removeSkill(player.storage.qysj_juyan);
                    game.log(player, '失去了技能', '#g【' + get.translation(player.storage.qysj_juyan) + '】');
                }
                const skills = trigger.player.getSkills(true, false);
                for (let s of skills) {
                    let group = lib.skill[s].group || [];
                    if (typeof group == 'string') {
                        if (group == skill) {
                            skill = s;
                        }
                    } else {
                        for (const item of group) {
                            if (item == skill) {
                                skill = s;
                            }
                        }
                    }
                }
                player.storage.qysj_juyan = skill;
                player.addSkillLog(skill);
                player.markSkill('qysj_juyan');
            }
        },
    },
    qysj_wenku: {
        enable: 'phaseUse',
        audio: 'yiji',
        usable: 1,
        filter(event, player) {
            return player.storage.qysj_juyan;
        },
        content() {
            player.removeSkill(player.storage.qysj_juyan);
            game.log(player, '失去了技能', '#g【' + get.translation(player.storage.qysj_juyan) + '】');
            const names = [];
            for (let i of game.players) {
                //QQQ
                names.add(i.name);
                names.add(i.name1);
                names.add(i.name2);
            }
            for (const i of game.dead) {
                names.add(i.name);
                names.add(i.name1);
                names.add(i.name2);
            }
            let list = get.gainableSkills(function (info, skill, name) {
                if (names.includes(name)) {
                    return false;
                }
                return true;
            });
            let skill = list.randomGet();
            player.storage.qysj_juyan = skill;
            player.addSkillLog(skill);
            player.markSkill('qysj_juyan');
        },
        ai: {
            order: 5,
            result: {
                player: 1,
            },
        },
    },
