    qysj_sese: {
        enable: 'phaseUse',
        audio: 'ext:猫猫叹气/audio:2',
        usable: 1,
        filterTarget(card, player, target) {
            return player != target && !target.hasSkill('qysj_qingliu');
        },
        content() {
            'step 0';
            player.say('我可以和你涩涩吗？');
            target.chooseBool(get.translation(player) + '向你发起涩涩请求,是否同意与' + (player.hasSex('female') ? '她' : '他') + '涩涩？').set('ai', function () {
                if (get.attitude(target, player) > 0) {
                    return true;
                }
                if (target.countCards('he') > 1 && target.countCards('he') < 4 && !player.isDamaged()) {
                    return true;
                }
                return false;
            });
            ('step 1');
            if (result.bool) {
                let str = '可以,我们来涩涩吧.';
                if (player.sex == target.sex) {
                    if (player.sex == 'male') {
                        str = '来吧,我攻你受!!';
                    } else {
                        str = '小妹妹,让姐姐来好好疼爱你~';
                    }
                }
                target.say(str);
            } else {
                let str = '不可以哦,我已经有意中人了.';
                if (player.sex == target.sex) {
                    if (player.sex == 'male') {
                        str = '男同死开啊,谁要和你涩涩!';
                    } else {
                        str = '我不搞百合哦,我的性取向很正常.';
                    }
                }
                target.say(str);
                game.log(target, '拒绝与', player, '涩涩');
                player.chooseToDiscard(true);
                target.chooseToDiscard(true, 2, 'he');
                event.finish();
            }
            ('step 2');
            event.time = get.utc();
            ('step 3');
            const delay = 8400 - (get.utc() - event.time);
            if (delay > 0) {
                event.dialog = ui.create.dialog(get.translation(player) + '与' + get.translation(target) + '正在涩涩...' + (_status.connectMode ? '' : '<br>(点击屏幕可立即高潮并结束涩涩)'));
                event.videoId = lib.status.videoId++;
                game.broadcast('createDialog', get.translation(player) + '与' + get.translation(target) + '正在涩涩...');
                game.pause();
                event.pingcai_delayed = true;
                setTimeout(function () {
                    if (event.pingcai_delayed == true) {
                        delete event.pingcai_delayed;
                        game.resume();
                    }
                }, delay);
                if (!_status.connectMode) {
                    event.forceMine = true;
                    event.custom.replace.window = function () {
                        if (event.pingcai_delayed == true) {
                            delete event.forceMine;
                            delete event.pingcai_delayed;
                            game.resume();
                        }
                    };
                }
                game.log(player, '与', target, '涩涩中……');
            }
            ('step 4');
            player.recover();
            game.asyncDraw([player, target], 2);
        },
        ai: {
            basic: {
                order: 9,
            },
            result: {
                player(player, target) {
                    if (get.attitude(player, target) > 0) {
                        return 10;
                    }
                    return 1;
                },
            },
        },
    },
