    qysj_diyue: {
        audio: 'ext:猫猫叹气/audio:2',
        trigger: { global: 'phaseEnd' },
        forced: true,
        filter(event, player) {
            const history = event.player.getHistory('useCard');
            return history && history.length;
        },
        content() {
            let history = trigger.player.getHistory('useCard'),
                types = [],
                cards = [];
            for (const i of history) {
                types.add(get.type2(i.card));
            }
            if (!types.length) {
                return;
            }
            for (const i of types) {
                let list = [];
                get.cardPile(function (card) {
                    if (get.type2(card) == i) {
                        list.push(card);
                    }
                });
                if (list.length) {
                    cards.push(list.randomGet());
                }
            }
            if (!cards.length) {
                return;
            }
            player.gain(cards, 'draw2');
        },
    },
    qysj_tonghua: {
        audio: 'ext:猫猫叹气/audio:2',
        trigger: {
            global: 'qmmUseSkillEnd',
        },
        logTarget: 'player',
        check(event, player) {
            return get.attitude(player, event.player) < 0;
        },
        filter(event, player) {
            if (event.player == player) {
                return false;
            }
            let skill = event.skill;
            const skills = event.player.getSkills(true, false);
            for (let s of skills) {
                let group = lib.skill[s].group || [];
                if (typeof group == 'string') {
                    if (group == skill) {
                        skill = s;
                    }
                } else {
                    for (const item of group) {
                        if (item == skill) {
                            skill = s;
                        }
                    }
                }
            }
            if (skill == event.skill && !skills.includes(skill)) {
                return false;
            }
            return lib.skill[skill] && lib.translate[skill] && lib.translate[skill + '_info'];
        },
        prompt2(event, player) {
            return '令' + get.translation(event.player) + '失去技能【' + get.translation(event.skill) + '】,你失去技能【同化】';
        },
        content() {
            let skill = trigger.skill;
            const skills = trigger.player.getSkills(true, false);
            for (let s of skills) {
                let group = lib.skill[s].group || [];
                if (typeof group == 'string') {
                    if (group == skill) {
                        skill = s;
                    }
                } else {
                    for (const item of group) {
                        if (item == skill) {
                            skill = s;
                        }
                    }
                }
            }
            trigger.player.removeSkill(skill);
            game.log(trigger.player, '失去了技能', '#g【' + get.translation(skill) + '】');
            player.removeSkill('qysj_tonghua');
            game.log(player, '失去了技能', '#g【同化】');
            player.storage.qysj_tonghua = [trigger.player, skill];
            player.addSkill('qysj_tonghua2');
            player.gainMaxHp();
            player.recover();
            trigger.player.gainMaxHp();
            trigger.player.recover();
        },
    },
