    qysj_xinyang: {
        audio: 'ext:猫猫叹气/audio:2',
        trigger: { player: 'damageEnd' },
        usable: 1,
        check(event, player) {
            if (player.isDamaged()) {
                return true;
            }
            return false;
        },
        content() {
            'step 0';
            player.judge(function (card) {
                switch (card.suit) {
                    case 'heart':
                        return player.maxHp > player.hp ? 1 : 0;
                    case 'diamond': {
                        if (player.isDamaged()) {
                            if (player.getDamagedHp() > 1) {
                                return 2;
                            } else {
                                return 1;
                            }
                        } else {
                            return 0;
                        }
                    }
                    case 'club':
                        return -1;
                    case 'spade': {
                        if (!player.countCards('h') && !player.storage.shaluzhuangtai) {
                            return 1;
                        } else {
                            return -2;
                        }
                    }
                }
            });
            ('step 1');
            if (result.suit != 'spade') {
                event.finish();
            }
            switch (result.suit) {
                case 'heart': {
                    player.recover();
                    break;
                }
                case 'diamond': {
                    player.recover(2);
                    break;
                }
                case 'club': {
                    player.damage();
                    break;
                }
                case 'spade': {
                    let str = '';
                    if (!player.countCards('h')) {
                        if (!player.storage.shaluzhuangtai) {
                            str = '(无牌可弃,改为进入<杀戮>状态)';
                        } else {
                            str = '(无牌可弃,且你已进入<杀戮>状态)';
                        }
                    }
                    let list = [],
                        list2 = ['受到两点伤害', '弃置全部手牌' + str];
                    list.push('选项一');
                    if (player.countCards('h') || !player.storage.shaluzhuangtai) {
                        list.push('选项二');
                    }
                    player
                        .chooseControl(list)
                        .set('choiceList', list2)
                        .set('ai', function (target) {
                            if (list.length > 1) {
                                return '选项二';
                            }
                            return '选项一';
                        });
                    break;
                }
            }
            ('step 2');
            if (result.control == '选项一') {
                player.damage(2);
            } else {
                if (player.countCards('h')) {
                    player.discard(player.getCards('h'));
                } else {
                    player.storage.shaluzhuangtai = true;
                    player.markSkill('qysj_shalu');
                    game.log(player, '进入了', '#g<杀戮>状态');
                }
            }
        },
        ai: {
            maixie: true,
            maixie_hp: true,
        },
    },
