    qmm_yuegong: {
        audio: 'ext:猫猫叹气/audio:2',
        derivation: ['qmm_yuebing', 'qmm_yutu', 'qmm_yueguijiu', 'qmm_jinchan'],
        init(player) {
            let list = ['qmm_yuebing', 'qmm_yutu', 'qmm_yueguijiu', 'qmm_jinchan'];
            for (let name of list) {
                if (!lib.card[name]) {
                    lib.card[name] = get.copy(lib.skill.qmm_baibaoxiang[name]);
                    lib.translate[name] = get.translation(name);
                    lib.translate[name + '_info'] = get.translation(name + '_info');
                }
                lib.inpile.add(name);
            }
            game.addGlobalSkill('qmm_jinchan2');
        },
        enable: ['chooseToUse'],
        prompt: '将♥️️️牌当做月饼,♦️️️牌当做玉兔,♣️️牌当做月桂酒,♠️️牌当做金蟾使用',
        viewAs(cards, player) {
            let name = false;
            switch (cards[0]?.suit) {
                case 'club':
                    name = 'qmm_yueguijiu';
                    break;
                case 'diamond':
                    name = 'qmm_yutu';
                    break;
                case 'spade':
                    name = 'qmm_jinchan';
                    break;
                case 'heart':
                    name = 'qmm_yuebing';
                    break;
            }
            if (name) {
                return { name: name };
            }
            return null;
        },
        check(card) {
            return 1;
        },
        position: 'hes',
        filterCard(card, player, event) {
            event = event || _status.event;
            const filter = event._backup.filterCard;
            let name = card.suit;
            if (name == 'club' && filter({ name: 'qmm_yueguijiu', cards: [card] }, player, event)) {
                return true;
            }
            if (name == 'diamond' && filter({ name: 'qmm_yutu', cards: [card] }, player, event)) {
                return true;
            }
            if (name == 'spade' && filter({ name: 'qmm_jinchan', cards: [card] }, player, event)) {
                return true;
            }
            if (name == 'heart' && filter({ name: 'qmm_yuebing', cards: [card] }, player, event)) {
                return true;
            }
            return false;
        },
        filter(event, player) {
            const filter = event.filterCard;
            if (filter({ name: 'qmm_yutu' }, player, event) && player.countCards('hes', { suit: 'diamond' })) {
                return true;
            }
            if (filter({ name: 'qmm_yueguijiu' }, player, event) && player.countCards('hes', { suit: 'club' })) {
                return true;
            }
            if (filter({ name: 'qmm_yuebing' }, player, event) && player.countCards('hes', { suit: 'heart' })) {
                return true;
            }
            if (filter({ name: 'qmm_jinchan' }, player, event) && player.countCards('hes', { suit: 'spade' })) {
                return true;
            }
            return false;
        },
        ai: {
            order(item, player) {
                return 6;
            },
        },
        hiddenCard(player, name) {
            if (name == 'qmm_jinchan') {
                return player.countCards('hes', { suit: 'spade' }) > 0;
            }
            if (name == 'qmm_yuebing') {
                return player.countCards('hes', { suit: 'heart' }) > 0;
            }
            if (name == 'qmm_yueguijiu') {
                return player.countCards('hes', { suit: 'club' }) > 0;
            }
            if (name == 'qmm_yutu') {
                return player.countCards('hes', { suit: 'diamond' }) > 0;
            }
        },
    },
