    qmm_duzhang: {
        audio: 'ext:猫猫叹气/audio:2',
        enable: ['chooseToUse', 'chooseToRespond'],
        hiddenCard(player, name) {
            if (!player.storage.qmm_duzhang) {
                player.storage.qmm_duzhang = 0;
            }
            let list = [];
            get.cardPile2(function (card) {
                if (!['qixingbaodao', 'duanjian', 'serafuku', 'yinfengyi', 'yonglv'].includes(card.name)) {
                    list.add(card.name);
                }
            });
            if (player.storage.qmm_duzhang < 2 && list.includes(name)) {
                return true;
            }
        },
        filter(event, player) {
            if (!player.storage.qmm_duzhang) {
                player.storage.qmm_duzhang = 0;
            }
            if (player.storage.qmm_duzhang >= 2) {
                return false;
            }
            let list = [];
            get.cardPile2(function (card) {
                if (!['qixingbaodao', 'duanjian', 'serafuku', 'yinfengyi', 'yonglv'].includes(card.name)) {
                    list.add(card.name);
                }
            });
            for (let i of list) {
                if (event.filterCard && event.filterCard({ name: i }, player, event)) {
                    return true;
                }
            }
            return false;
        },
        delay: false,
        forced: true,
        content() {
            'step 0';
            let evt = event.getParent(2);
            evt.set('qmm_duzhang', true);
            let dialog = ui.create.dialog('独掌', '选择要' + (evt.name != 'chooseToRespond' ? '使用' : '打出') + '的牌', 'hidden');
            const ygo = ui.cardPile.childNodes.length;
            //var yog=ui.discardPile.childNodes.length
            if (ygo > 0) {
                let nn;
                for (let i = 0; i < ygo; i++) {
                    let n = ui.cardPile.childNodes[i];
                    if (evt.name == '_wuxie') {
                        if (n.name == 'wuxie') {
                            nn = i + 1;
                            break;
                        }
                    } else if (evt.filterCard && evt.filterCard(n, player, evt)) {
                        let nn = i + 1;
                        break;
                    }
                }
                if (evt.name == '_wuxie' || evt.type != 'phase') {
                    dialog.addText('定位:第' + nn + '张');
                }
                event.cards = Array.from(ui.cardPile.childNodes);
                dialog.addSmall(event.cards);
            }
            player
                .chooseButton(dialog)
                .set('filterButton', function (button) {
                    if (['qixingbaodao', 'duanjian', 'serafuku', 'yinfengyi', 'yonglv'].includes(button.link.name)) {
                        return false;
                    }
                    if (evt.name == '_wuxie') {
                        return button.link.name == 'wuxie';
                    }
                    return evt.filterCard(button.link, _status.event.player, evt);
                })
                .set('ai', function (button) {
                    if (evt.name == '_wuxie' || evt.type != 'phase') {
                        return 1;
                    }
                    let player = _status.event.player;
                    if (['nanman', 'wanjian', 'jingleishan', 'chiyuxi', 'lebu', 'tmxk_qingguoqingcheng', 'tao', 'wuzhong', 'zengbin', 'dongzhuxianji', 'shuiyanqijunx'].includes(button.link.name)) {
                        return 1000 + Math.random();
                    }
                    return player.getUseValue(button.link);
                });
            ('step 1');
            let evt1 = event.getParent(2);
            if (result.bool && result.links && result.links.length) {
                let name = result.links[0].name;
                if (evt1.name == 'chooseToUse') {
                    game.broadcastAll(
                        function (result, name) {
                            lib.skill.qmm_duzhang_backup.viewAs = { name: name, cards: [result] };
                            lib.skill.qmm_duzhang_backup.prompt = '选择' + get.translation(result) + '的目标';
                        },
                        result.links[0],
                        name,
                    );
                    evt1.set('_backupevent', 'qmm_duzhang_backup');
                    evt1.backup('qmm_duzhang_backup');
                    evt1.set('openskilldialog', '选择' + get.translation(result.links[0]) + '的目标');
                    evt1.set('norestore', true);
                    evt1.set('custom', {
                        add: {},
                        replace: { window() { } },
                    });
                } else {
                    //if(_status.currentPhase==player){
                    if (!player.storage.qmm_duzhang) {
                        player.storage.qmm_duzhang = 0;
                    }
                    player.storage.qmm_duzhang++;
                    //	}
                    if (evt1.name == '_wuxie') {
                        evt1.wuxieresult = player;
                        evt1.wuxieresult2 = result.links[0];
                        evt1.goto(8);
                    } else {
                        evt1.result.card = result.links[0];
                        evt1.result.cards = [result.links[0]];
                        evt1.redo();
                    }
                    return;
                }
            }
            evt1.goto(0);
        },
        ai: {
            effect: {
                target(card, player, target, effect) {
                    if (get.tag(card, 'respondShan')) {
                        return 0.7;
                    }
                    if (get.tag(card, 'respondSha')) {
                        return 0.7;
                    }
                },
            },
            order: 5,
            respondShan: true,
            respondSha: true,
            result: {
                player(player) {
                    if (_status.event.dying) {
                        return get.attitude(player, _status.event.dying);
                    }
                    return 1;
                },
            },
        },
        group: 'qmm_duzhang2',
    },
