            for (let name of ['sha', 'shan', 'tao']) {
                let card = { name: name };
                if (name == 'sha') {
                    if (
                        game.hasPlayer(function (current) {
                            return current.getCards('h').length && current.isMaxHandcard();
                        })
                    ) {
                        if (event.filterCard && event.filterCard(card, player, event)) {
                            event.cards.add('sha');
                        }
                        for (let nature of lib.inpile_nature.concat(['kami'])) {
                            card.nature = nature;
                            if (event.filterCard && event.filterCard(card, player, event)) {
                                event.cards.add('sha');
                            }
                        }
                    }
                } else {
                    if (
                        game.hasPlayer(function (current) {
                            return current.getCards('ej').length;
                        })
                    ) {
                        const cardx = { name: name };
                        if (event.filterCard && event.filterCard(cardx, player, event)) {
                            event.cards.add(name);
                        }
                    }
                }
            }
            return event.cards && event.cards.length;
