            if (event.cards && event.cards.length) {
                if (event.cards.includes('sha') && shax.length && max) {
                    return true;
                }
                if ((event.cards.includes('shan') || event.cards.includes('tao')) && shanx.length) {
                    return true;
                }
            }
            return false;
